user_prompt:
method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0 // The list must not be empty
    ensures |result| == |xs| - 1 // The length of the result is one less than the input
    ensures forall i :: 0 <= i < |result| ==> result[i] == xs[i + 1] * (i + 1) // Each coefficient is multiplied by its power
{
    var n := |xs|; 
    result := [];
    var i := 0;

    while i < n - 1
        invariant 0 <= i <= n - 1 // i is within the bounds of the input list
        invariant |result| == i // The size of the result corresponds to the number of derivatives calculated
    {
        result := result + [xs[i + 1] * (i + 1)];
        i := i + 1;
    }
}
